        }
    }

    override fun onForgotten() {
        verboseTrace("Compose:DisposableEffect:dispose") {
            onDispose?.dispose()
            onDispose = null
        }
    }

    override fun onAbandoned() {
        // Nothing to do as [onRemembered] was not called.
    }
}

