        var context = parentCoroutineContext + this
        @OptIn(ComposeToolingApi::class)
        if (ComposeToolingFlags.isVerboseTracingEnabled) {
            context += LaunchedEffectTracingContext
        }
        scope = CoroutineScope(context)
