    public var alpha: Float

    /** Blending algorithm used by the shadow. Defaults to [BlendMode.SrcOver] */
    public var blendMode: BlendMode

    /** Offset of the shadow. Defaults to [Offset.Zero]. */
    public var offset: Offset
}

